-- =============================================================================
-- Catálogo distribuidor: Siemon agosto 2026 + Acceso-Alarma septiembre 2026
-- Supabase → SQL Editor → Run (idempotente por marca+modelo)
--
-- 253 SKU Siemon + 258 SKU Acceso/Alarma (Hikvision, Hikfire,
-- Ubiquiti Access, Omegasat). Total 511.
-- El PDF Ezviz de octubre NO se vuelve a cargar (ya está en Productos).
--
-- costo  = precio de lista del PDF (USD)
-- precio = mismo valor (sin margen de reventa inventado)
-- utilidad = 0
-- cantidad de filas NUEVAS = 0 (no toca stock de filas ya existentes)
-- No usa updated_at (esa columna no está en products de producción).
-- =============================================================================

begin;

create temporary table cat_dist_2026 (
  marca text not null,
  modelo text not null,
  nombre text not null,
  categoria text not null,
  costo numeric(14,2) not null,
  descripcion text,
  estatus text not null,
  primary key (marca, modelo)
);


update public.products p
set
  nombre = e.nombre,
  categoria = e.categoria,
  marca = e.marca,
  descripcion = e.descripcion,
  descripcion2 = 'Lista distribuidor 2026 · ' || e.estatus,
  costo = e.costo,
  precio = e.costo,
  utilidad = 0
from cat_dist_2026 e
where lower(btrim(p.modelo)) = lower(btrim(e.modelo))
  and (
    p.marca is null
    or btrim(p.marca) = ''
    or lower(btrim(p.marca)) = lower(btrim(e.marca))
  );

  nombre,
  categoria,
  marca,
  modelo,
  descripcion,
  descripcion2,
  costo,
  precio,
  utilidad,
  cantidad
)
select
  e.nombre,
  e.categoria,
  e.marca,
  e.modelo,
  e.descripcion,
  'Lista distribuidor 2026 · ' || e.estatus,
  e.costo,
  e.costo,
  0,
  0
from cat_dist_2026 e
where not exists (
  select 1
  from public.products p
  where lower(btrim(p.modelo)) = lower(btrim(e.modelo))
    and (
      p.marca is null
      or btrim(p.marca) = ''
      or lower(btrim(p.marca)) = lower(btrim(e.marca))
    )
);

commit;

select marca, count(*) as n
from public.products
where lower(btrim(coalesce(marca, ''))) in ('siemon', 'hikvision', 'hikfire', 'ubiquiti', 'omegasat')
group by 1
order by 1;
